local UIMainBattlePanelCell = Class("UIMainBattlePanelCell")
local challengeRewardCount = 3

function UIMainBattlePanelCell:__init()
    self._position = 0
end

function UIMainBattlePanelCell:__delete()
    self._position = 0
end

function UIMainBattlePanelCell:Awake()
    self.EventRewardChange = Events.AddListener(Constants.EventNames.MainQuestChapterRewardChange, Bind(self, self.OnRewardChange))
end

function UIMainBattlePanelCell:Start()
end

function UIMainBattlePanelCell:OnRewardChange()
    if not self._data then
        return
    end
    CfUtils.SetActive(self.ChapterReward.transform:Find("Finish"), QuestConfMgr:GetInstance():IsDrawChapterReward(self._data.id))
end 

function UIMainBattlePanelCell:Initialize()
    SetButtonAction(self.controller.gameObject, function()
        if self._isPlayStory then
            return
        end
        if not self._data then
            return 
        end
        if checkNumber(self._data.id) == -1 then
            GameUtils.Toast(localize("敬请期待"))
            return
        end
        local type = checkNumber(KCookie.Get("MainQuestType"))

        if checkNumber(self._position) >= 0.45 and checkNumber(self._position) <= 0.55 then
            local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockMainChapter(self._data.id, type == Constants.IDType.QuestMainChallenge)
            if not isUnlock then
                GameUtils.Toast(err)
                return
            end
            local open =  ThirdDownloadManager:IsMainOpenDownloadThirdPackage(self._data.id)
            if open then
                UIModule.OpenDialog({ id = Constants.UITypeIds.ThirdPackageDownloadDialog})
                return
            end
            if type == Constants.IDType.QuestMainChallenge then
                KCookie.Set("LastSelectHardChapterId", self._data.id)
            else
                KCookie.Set("LastSelectChapterId", self._data.id)
            end

            self:HandleMovie(function()
                KCookie.Set("UIMainBattlePanelDialogIndex", 1)
                xTry(function()
                    local startDownloaded = CS.Engine.Tools.PlayerPrefsUtility.GetEncryptedString("AUDIO_DOWNLOAD", '0')
                    local chapterId = QuestConfMgr:GetInstance():GetCurChapterId()
                    if startDownloaded == '0' and chapterId >= 107  then
                        local hasPromoted = CfUtils.GetLocalData("HAS_PROMOTED", "0")
                        if hasPromoted == '0' then
                            CfUtils.WriteLocalData('HAS_PROMOTED', '1')
                            ---未开始下载
                            local social = AppService:GetInstance():GetSocialLine()
                            if not isNull(social.batchSyncer) and social.batchSyncer.IsReady and not social.batchSyncer:IsSuccess() then
                                GameUtils.SecondConfirm(localize('是否下载音频资源？'), function()
                                    KCookie.Set("SettingOpenType", 3)
                                    CfUtils.DialogOpen(Constants.UITypeIds.UISettingDialog)
                                    return true
                                end, function()
                                    UIModule.OpenDialog({ id = Constants.UITypeIds.UIMainChapterDialog, parameters = { chapterId =  self._data.id, type = type} }, {
                                        {id = Constants.UITypeIds.UIMainBattlePanelDialog}
                                    })
                                end, localize('若未下载主线音频资源，则剧情将<color=#ff0000>无法播放语音</color>'), 10, nil, nil, localize('为了您完整的剧情体验，建议您前往下载完整主线音频资源'))
                            else
                                UIModule.OpenDialog({ id = Constants.UITypeIds.UIMainChapterDialog, parameters = { chapterId =  self._data.id, type = type} }, {
                                    {id = Constants.UITypeIds.UIMainBattlePanelDialog}
                                })
                            end
                        else
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UIMainChapterDialog, parameters = { chapterId =  self._data.id, type = type} }, {
                                {id = Constants.UITypeIds.UIMainBattlePanelDialog}
                            })
                        end
                    else
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UIMainChapterDialog, parameters = { chapterId =  self._data.id, type = type} }, {
                            {id = Constants.UITypeIds.UIMainBattlePanelDialog}
                        })
                    end
                end)
            end)
        else
            local go = self.controller.gameObject.transform.parent.parent
            local fsv = go.transform:GetComponent(FancyScrollView)

            local ind = self:GetIdPos()
            fsv:JumpTo(ind)
        end
    end)
end

function UIMainBattlePanelCell:GetIdPos()
    local type = checkNumber(KCookie.Get("MainQuestType"))
    local isChallenge = (type == Constants.IDType.QuestMainChallenge)
    local t = isChallenge and CfUtils.GetCfTable(AutoIds.IdSetting6122) or CfUtils.GetCfTable(AutoIds.IdSetting281)
    local count = 0
    for k, v in pairs(t) do
        local vo = isChallenge and ChapterHardVo.New() or ChapterVo.New()
        vo:FillVo(v)
        if checkNumber(vo.id) == checkNumber(self._data.id) then
            return count
        end
        count = count + 1
    end 
end

function UIMainBattlePanelCell:HandleMovie(cb)
    local vo = QuestConfMgr:GetInstance():GetChapterVoByID(self._data.id)
    if not vo then
        cb()
        return
    end

    local id = CfUtils.GetLocalData("MainChapterShowMovie")
    if checkNumber(id) >= checkNumber(self._data.id) then
        cb()
        return
    end

    ChapterUtils.StartChapterEnter(self._data.id, function(go)
        self._isPlayStory = true
        --self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)

        CfUtils.SetTopCommonActive(false, false)
        self._plotGo = go
    end, function()
        --GameUtils.PlayMainBGM()
        
        cs_coroutine.start(function()
            KCookie.Set("UIMainBattlePanelDialogIndex", 1)
            local type = checkNumber(KCookie.Get("MainQuestType"))
            coroutine.yield(UIModule.OpenDialog({ id = Constants.UITypeIds.UIMainChapterDialog, parameters = { chapterId =  self._data.id, type = type} }, {
                {id = Constants.UITypeIds.UIMainBattlePanelDialog}
            }))
                    --self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
            CfUtils.SetTopCommonActive(true, false)
            KTool.SafeDelete(self._plotGo)
        end)
    end)
end 

