        return
    end
    self._data = data
    --敬请期待
    if checkNumber(data.id) == -1 then
        CfUtils.SetActive(self.StarLevel, false)
        CfUtils.SetActive(self.StarLevelSelect, false)
        CfUtils.SetActive(self.TextName, false)
        CfUtils.SetActive(self.TextNum, false)
        CfUtils.SetActive(self.TextNameSelect, false)
        CfUtils.SetActive(self.TextNumSelect, false)
        CfUtils.SetActive(self.Lock, true)
        CfUtils.SetActive(self.LockSelect, true)
        CfUtils.SetActive(self.Finish, false)
        CfUtils.SetActive(self.FinishSelect, false)

        CfUtils.SetActive(self.NoneSelect, true)
        CfUtils.SetActive(self.None, true)
        CfUtils.SetActive(self.Content, false)
        CfUtils.SetActive(self.ContentSelect, false)
        self.ImgChapter.transform:GetComponent(typeof(CS.Engine.UI.UIGrayGraphics)):MarkGray(true)
        self.ImgChapterSelect.transform:GetComponent(typeof(CS.Engine.UI.UIGrayGraphics)):MarkGray(true)

        --self.ImgDecorate.transform:GetComponent(typeof(CS.Engine.UI.UIGrayGraphics)):MarkGray(not isUnlock)
        CfUtils.FillImage(self.ImgChapter, data.bigPic)
        CfUtils.FillImage(self.ImgChapterSelect, data.pic)

        CfUtils.SetActive(self.ImgNewSelect, false)
        CfUtils.SetActive(self.ImgNew, false)

        CfUtils.SetActive(self.NotSelect.transform:Find("Layout/CommonRedPoint"), false)
        CfUtils.SetActive(self.Select.transform:Find("Layout/CommonRedPointSelect"), false)
        return
    else
        CfUtils.SetActive(self.ContentSelect, true)
        CfUtils.SetActive(self.NoneSelect, false)
        CfUtils.SetActive(self.None, false)
        CfUtils.SetActive(self.Content, true)
    end

    local type = checkNumber(KCookie.Get("MainQuestType"))
    local isUnlock, err
    local isPass

    local isChallenge = (type == Constants.IDType.QuestMainChallenge)
    --挑战
    if isChallenge then
        isUnlock, err = QuestConfMgr:GetInstance():IsUnlockChapter(data.id,true)
        isPass = QuestConfMgr:GetInstance():IsPassChallengeChapter(data.id)
    else
        isUnlock, err = QuestConfMgr:GetInstance():IsUnlockChapter(data.id)
        isPass = QuestConfMgr:GetInstance():IsPassChapter(data.id)
    end
    CfUtils.SetActive(self.TextName, isUnlock)
    CfUtils.SetActive(self.TextNum, isUnlock)
    CfUtils.SetActive(self.TextNumSelect, true)
    CfUtils.SetActive(self.TextNameSelect, true)
    --CfUtils.SetActive(self.TextNameSelect, isUnlock)
    --CfUtils.SetActive(self.TextNumSelect, isUnlock)

    CfUtils.SetActive(self.StarLevel, false)
    CfUtils.SetActive(self.StarLevelSelect, false)
    CfUtils.SetActive(self.HardChapterReward, isChallenge)
    if isChallenge then
        --[[local allNum, curNum = QuestConfMgr:GetInstance():GetChapterStarGetNum(data.id)
        CfUtils.FillText(self.TextNumber, curNum)
        CfUtils.FillText(self.TextNumber2, "/"..allNum)
        CfUtils.SetUISwitchText(self.TextNumber, QuestConfMgr:GetInstance():IsDrawChapterAllReward(data.id) and 2 or 1)
        CfUtils.FillText(self.TextNumberNotSelect, curNum)
        CfUtils.FillText(self.TextNumber2NotSelect, "/"..allNum)
        CfUtils.SetUISwitchText(self.TextNumberNotSelect, QuestConfMgr:GetInstance():IsDrawChapterAllReward(data.id) and 2 or 1)]]
        self:FillChallengeReward(data.showRewardIds)
    end

    CfUtils.FillImage(self.ImgChapter, data.bigPic)
    CfUtils.FillImage(self.ImgChapterSelect, data.pic)
    CfUtils.FillText(self.TextNum, data.number)
    local chaptername1 = string.gsub(data.name, '\\n', '')
    CfUtils.FillText(self.TextName, chaptername1)
    CfUtils.FillText(self.TextNumSelect, data.number)

    local chaptername2 = string.gsub(data.name, '\\n', '\n')
    CfUtils.FillText(self.TextNameSelect, chaptername2)
    CfUtils.FillText(self.Select.transform:Find("LayoutDesc/ImgLine/TextNumSelectShadow"), data.number)

    CfUtils.FillText(self.TextNumber1, "x"..data.bigRewardNum)
    CfUtils.FillImage(self.ImgGoodsIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(data.bigRewardId))
    CfUtils.SetActive(self.ChapterReward.transform:Find("Finish"), QuestConfMgr:GetInstance():IsDrawChapterReward(data.id))

    self.ImgChapter.transform:GetComponent(typeof(CS.Engine.UI.UIGrayGraphics)):MarkGray(not isUnlock)
    --self.ImgChapterSelect.transform:GetComponent(typeof(CS.Engine.UI.UIGrayGraphics)):MarkGray(not isUnlock)
    self.ImgChapterSelect.transform:GetComponent(typeof(CS.Engine.UI.UIGrayGraphics)):MarkGray(not isUnlock)
    CfUtils.SetActive(self.Lock, not isUnlock)
    CfUtils.SetActive(self.LockSelect, not isUnlock)

    if isUnlock then
        CfUtils.SetActive(self.Finish, isPass)
        CfUtils.SetActive(self.FinishSelect, isPass)

        if isPass then
        end
    else
        CfUtils.FillText(self.TextCondition, err)
        CfUtils.FillText(self.TextConditionSelect, err)
        CfUtils.SetActive(self.Finish, false)
        CfUtils.SetActive(self.FinishSelect, false)
    end
    CfUtils.SetActive(self.Select.transform:Find("CurrentSelect"), isUnlock and not isPass)
    local id = 0 
    if isChallenge then
        id = QuestConfMgr:GetInstance():GetCurNeedChallengeQuestId(self._data.id)
    else
        id = QuestConfMgr:GetInstance():GetCurChapterNeedQuestId(self._data.id)
    end
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
    if vo then
        CfUtils.FillText(self.Select.transform:Find("CurrentSelect/TextNumber"), vo.label)
    end

    local go1 = self.NotSelect.transform:Find("Layout/CommonRedPoint")
    local go2 = self.Select.transform:Find("Layout/CommonRedPointSelect")

    if isChallenge then
        local isCanDraw = QuestConfMgr:GetInstance():IsCanChapterRewardDraw(data.id)
        CfUtils.SetActive(go1, isCanDraw)
        CfUtils.SetActive(go2, isCanDraw)
    else
        local isCanDraw = QuestConfMgr:GetInstance():IsSideRedPointActive(data.id)
        CfUtils.SetActive(go1, isCanDraw)
        CfUtils.SetActive(go2, isCanDraw)
    end

    local allQuestIds = {}
    if isChallenge then
        allQuestIds = QuestConfMgr:GetInstance():GetChallengeChapterIds(data.id)
    else
        allQuestIds = QuestConfMgr:GetInstance():GetChapterIds(data.id)
    end

    local isNew = false
    if checkNumber(allQuestIds[1]) > 0 then
        isNew = not QuestConfMgr:GetInstance():IsPassQuest(allQuestIds[1])
    end

    CfUtils.SetActive(self.ImgNewSelect, isNew and isUnlock)
    CfUtils.SetActive(self.ImgNew, isNew and isUnlock)
end

function UIMainBattlePanelCell:FillChallengeReward(showRewardIds)
    local rewardData = showRewardIds
    for i = 1, challengeRewardCount do
        local item = self["GoodNode"..i]
        if not isNull(item) then
            if not isNull(rewardData[i]) and checkNumber(rewardData[i]) > 0 then
                local goodNodeMB = CfUtils.GetLuaScr(item, "Game.Behaviours.GoodNodeMB")
                if goodNodeMB then
                    goodNodeMB:Reload({goodsId = checkNumber(rewardData[i]), isShowNo = false})
                    goodNodeMB:FillGoodsStarInfo(checkNumber(rewardData[i]))
                end
                KTool.SetActive(item.gameObject,true)
            else
                KTool.SetActive(item.gameObject,false)
            end

        end
    end
end

function UIMainBattlePanelCell:UpdatePosition(position)
    self.AnimRoot:Play(CS.UnityEngine.Animator.StringToHash("Play"), -1, position)
    self.AnimRoot.speed = 0

    self._position = position
    if self._data then
        local isUnlock, err = false, ""

        if checkNumber(self._data.id) == -1 then
        else
            local type = checkNumber(KCookie.Get("MainQuestType"))
            local isChallenge = (type == Constants.IDType.QuestMainChallenge)
            --挑战
            if isChallenge then
                isUnlock, err = QuestConfMgr:GetInstance():IsUnlockChapter(self._data.id,isChallenge)
            else
                isUnlock, err = QuestConfMgr:GetInstance():IsUnlockChapter(self._data.id)
            end
        end

        if not (checkNumber(self._data.ind) == checkNumber(self.BtnChapterList.currentPosition)) then
            CfUtils.SetActive(self.NotSelect, true)
            CfUtils.SetActive(self.Select, false)
        else
            CfUtils.SetActive(self.NotSelect, false)
            CfUtils.SetActive(self.Select, true)

            if isUnlock then
                CfUtils.PlayAnimator(self.Select, "Open")
            else
                CfUtils.PlayAnimator(self.Select, "Unlock")
            end
        end
    end
end

function UIMainBattlePanelCell:OnDestroy()
    Events.RemoveListener(Constants.EventNames.MainQuestChapterRewardChange, self.EventRewardChange)
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIMainBattlePanelCell